import{_ as l,b as a,c as t,d as i}from"./chunks/framework.D4cM_aKq.js";const p=JSON.parse('{"title":"从一个小问题开始拆解","description":"把模糊的需求变成可以验证的步骤，是编程之外同样重要的能力。","frontmatter":{"layout":"article","title":"从一个小问题开始拆解","description":"把模糊的需求变成可以验证的步骤，是编程之外同样重要的能力。","date":"2026-10-13","category":"计算机基础","directory":"方法与实践","tags":["软件工程","学习笔记"],"sample":true},"headers":[{"level":2,"title":"先写清楚输入与输出","slug":"先写清楚输入与输出","link":"#先写清楚输入与输出","children":[]},{"level":2,"title":"找到最小可验证步骤","slug":"找到最小可验证步骤","link":"#找到最小可验证步骤","children":[]},{"level":2,"title":"留意边界","slug":"留意边界","link":"#留意边界","children":[]},{"level":2,"title":"验证之后再抽象","slug":"验证之后再抽象","link":"#验证之后再抽象","children":[]},{"level":2,"title":"留下一份记录","slug":"留下一份记录","link":"#留下一份记录","children":[]}],"relativePath":"journal/fundamentals/problem-solving.md","filePath":"journal/fundamentals/problem-solving.md"}'),r={name:"journal/fundamentals/problem-solving.md"};function n(o,e,s,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="先写清楚输入与输出" tabindex="-1">先写清楚输入与输出 <a class="header-anchor" href="#先写清楚输入与输出" aria-label="Permalink to &quot;先写清楚输入与输出&quot;">​</a></h2><p>遇到复杂问题时，可以先记录已知条件、期望结果，以及能够接受的限制。</p><p>比如“给个人网站添加搜索”，可以进一步描述为：输入关键词，返回与标题、标签或正文匹配的文章和项目。</p><h2 id="找到最小可验证步骤" tabindex="-1">找到最小可验证步骤 <a class="header-anchor" href="#找到最小可验证步骤" aria-label="Permalink to &quot;找到最小可验证步骤&quot;">​</a></h2><p>把工作拆成能够独立检查的部分：读取内容、构建索引、匹配关键词、展示结果和打开页面。</p><p>每一步都保留一个具体例子，比一次处理所有细节更容易定位问题。</p><h2 id="留意边界" tabindex="-1">留意边界 <a class="header-anchor" href="#留意边界" aria-label="Permalink to &quot;留意边界&quot;">​</a></h2><ul><li>没有内容时，界面如何提示？</li><li>输入为空时，应该显示什么？</li><li>找不到结果时，用户怎样继续？</li><li>使用键盘时，能否完成相同操作？</li></ul><h2 id="验证之后再抽象" tabindex="-1">验证之后再抽象 <a class="header-anchor" href="#验证之后再抽象" aria-label="Permalink to &quot;验证之后再抽象&quot;">​</a></h2><p>先让真实场景得到解决，再决定哪些重复逻辑值得提取。好的抽象来自对变化的理解。</p><h2 id="留下一份记录" tabindex="-1">留下一份记录 <a class="header-anchor" href="#留下一份记录" aria-label="Permalink to &quot;留下一份记录&quot;">​</a></h2><p>写下问题的原因、采取的方法和验证方式。未来再次遇到类似情况时，这些记录会比零散的代码片段更有帮助。</p>',12)])])}const m=l(r,[["render",n]]);export{p as __pageData,m as default};
